#!/usr/bin/env python3
"""MiniMax AI Review —— 读取 /tmp/pr_diff.txt，调用 MiniMax chat/completions，
把审查结果作为评论贴到对应 PR。

从 minimax-pr-review.yml 的内嵌 heredoc 抽出（原内嵌版因缩进破坏 YAML block
scalar，自 2026-10-23 起每次 push 都产生必失败 run）。抽成独立脚本后可以
py_compile 校验，不再受 YAML 缩进与 shell 转义影响。

必需环境变量：
  MINIMAX_API_KEY   —— 未设置时跳过（exit 0），并写入 GITHUB_STEP_SUMMARY
  PR_TITLE / PR_NUMBER / REPO
可选：
  MINIMAX_BASE_URL  —— 默认 https://api.minimax.chat/v1
  MINIMAX_MODEL     —— 默认 MiniMax-Text-01
  FILES             —— 变更文件列表（仅用于提示词）
  GITHUB_TOKEN      —— 未设置时无法回帖，打印错误并以非零码退出
"""

import json
import os
import sys
import urllib.request

DIFF_PATH = "/tmp/pr_diff.txt"
DEFAULT_BASE_URL = "https://api.minimax.chat/v1"
DEFAULT_MODEL = "MiniMax-Text-01"


def main() -> int:
    api_key = os.environ.get("MINIMAX_API_KEY", "")
    if not api_key:
        summary = os.environ.get("GITHUB_STEP_SUMMARY")
        notice = "MINIMAX_API_KEY 未设置，MiniMax Review 跳过（不失败）。"
        if summary:
            with open(summary, "a", encoding="utf-8") as fh:
                fh.write(f"> ⚠️ {notice}\n")
        print(notice)
        return 0

    with open(DIFF_PATH, "r", encoding="utf-8") as f:
        diff = f.read()

    pr_title = os.environ.get("PR_TITLE", "")
    pr_number = os.environ.get("PR_NUMBER", "")
    repo = os.environ.get("REPO", "")
    files = os.environ.get("FILES", "")
    base_url = os.environ.get("MINIMAX_BASE_URL", DEFAULT_BASE_URL).rstrip("/")
    model = os.environ.get("MINIMAX_MODEL", DEFAULT_MODEL)

    prompt = (
        "你是 Kotlin Multiplatform 项目的代码审查专家。请审查以下 PR 的变更：\n\n"
        "PR 标题: " + pr_title + "\n变更文件: " + files + "\n\n代码变更：\n" + diff + "\n\n"
        "请审查以下方面：\n"
        "1. 架构一致性\n2. 业务逻辑位置\n3. KMP source-set 正确性\n"
        "4. Compose/UI 性能\n5. 协程/并发问题\n6. 回归风险\n\n"
        "请以 Markdown 格式输出审查结果，包含：总体评估、高/中/低严重性问题、"
        "做得好的地方。仅审查 Kotlin 文件，不要应用修复。"
    )

    messages = [
        {"role": "system", "content": "你是一个严格的代码审查专家。"},
        {"role": "user", "content": prompt},
    ]
    payload = {"model": model, "messages": messages, "temperature": 0.3, "max_tokens": 4000}

    req = urllib.request.Request(
        base_url + "/chat/completions",
        data=json.dumps(payload).encode("utf-8"),
        headers={"Authorization": "Bearer " + api_key, "Content-Type": "application/json"},
        method="POST",
    )
    with urllib.request.urlopen(req, timeout=60) as resp:
        result = json.loads(resp.read().decode("utf-8"))

    content = result.get("choices", [{}])[0].get("message", {}).get("content", "")
    body = "## MiniMax AI Review\n\n" + content + "\n\n---\n*This review was generated by MiniMax AI*\n"

    token = os.environ.get("GITHUB_TOKEN", "")
    if not token:
        print("GITHUB_TOKEN 未设置，无法回帖；审查结果仅打印。\n")
        print(body)
        return 1

    comment_req = urllib.request.Request(
        "https://api.github.com/repos/" + repo + "/issues/" + pr_number + "/comments",
        data=json.dumps({"body": body}).encode("utf-8"),
        headers={"Authorization": "token " + token, "Content-Type": "application/json"},
        method="POST",
    )
    with urllib.request.urlopen(comment_req) as comment_resp:
        comment_resp.read()
    print("Comment posted")
    return 0


if __name__ == "__main__":
    sys.exit(main())
